/**
 * @description Outband API: stable pseudonyms for users and tokens.
 *
 * Pseudonyms are HMAC-SHA256 values keyed by a server secret and scoped to
 * the viewing credential, so one client can correlate events but not
 * identify people. The key is generated by the server, stored in the
 * Outband settings collection, and never exposed through the API or logs.
 * Rotating the key (deleting the stored key) changes every pseudonym.
 * @license Apache-2.0
 */

'use strict';

const crypto = require('crypto');

const KEY_ID = 'pseudonym-key';

class Pseudonyms {
    constructor(store) { this.store = store; this.key = null; }

    async load() {
        let doc = await this.store.settings.findOne({ _id: KEY_ID });
        if ((doc == null) || (typeof doc.k != 'string')) {
            doc = { _id: KEY_ID, k: crypto.randomBytes(32).toString('base64'), created: Date.now() };
            await this.store.settings.upsert({ _id: KEY_ID }, doc);
        }
        this.key = Buffer.from(doc.k, 'base64');
    }

    _h(kind, scope, value) {
        return crypto.createHmac('sha256', this.key).update(kind + '\u0000' + String(scope) + '\u0000' + String(value)).digest('hex').substring(0, 16);
    }

    /** Pseudonym of a user as seen by one credential. */
    user(scope, userid) { return 'u_' + this._h('u', scope, userid); }

    /** Pseudonym of a token as seen by one credential. */
    token(scope, tokenId) { return 't_' + this._h('t', scope, tokenId); }

    /** Credential-independent pseudonym written into audit records at erasure. */
    erased(userid) { return 'u_' + this._h('erased', '', userid); }
}

module.exports = { Pseudonyms };
